import (
	"bufio"
	"fmt"
	"os"
)

type Edge struct {
	to int
}

func main() {
	in := bufio.NewReader(os.Stdin)
	var n, m int
	if _, err := fmt.Fscan(in, &n, &m); err != nil {
		return
	}

	f := make([]int, n)
	for i := 0; i < n; i++ {
		fmt.Fscan(in, &f[i])
	}

	g := make([][]int, n)
	gr := make([][]int, n)
	for i := 0; i < m; i++ {
		var a, b int
		fmt.Fscan(in, &a, &b)
		a--
		b--
		g[a] = append(g[a], b)
		gr[b] = append(gr[b], a)
	}

	// Kosaraju to find SCCs
	order := make([]int, 0, n)
	used := make([]bool, n)

	var dfs1 func(v int)
	dfs1 = func(v int) {
		used[v] = true
		for _, to := range g[v] {
			if !used[to] {
				dfs1(to)
			}
		}
		order = append(order, v)
	}

	for i := 0; i < n; i++ {
		if !used[i] {
			dfs1(i)
		}
	}

	comp := make([]int, n)
	for i := range comp {
		comp[i] = -1
	}
	var dfs2 func(v, c int)
	dfs2 = func(v, c int) {
		comp[v] = c
		for _, to := range gr[v] {
			if comp[to] == -1 {
				dfs2(to, c)
			}
		}
	}

	cc := 0
	for i := n - 1; i >= 0; i-- {
		v := order[i]
		if comp[v] == -1 {
			dfs2(v, cc)
			cc++
		}
	}

	// Build condensation DAG
	cg := make([][]int, cc)
	// remove duplicate edges using map per component (could be large, but fine)
	edgeSet := make(map[[2]int]struct{}, m)
	for v := 0; v < n; v++ {
		cv := comp[v]
		for _, to := range g[v] {
			ct := comp[to]
			if cv != ct {
				key := [2]int{cv, ct}
				if _, ok := edgeSet[key]; !ok {
					edgeSet[key] = struct{}{}
					cg[cv] = append(cg[cv], ct)
				}
			}
		}
	}

	// For each component, compute:
	// hasAssign: any node with f==1
	// hasUse: any node with f==2
	// hasAssignInside: any node with f==1 (same as hasAssign)
	hasAssign := make([]bool, cc)
	hasUse := make([]bool, cc)
	for v := 0; v < n; v++ {
		cid := comp[v]
		if f[v] == 1 {
			hasAssign[cid] = true
		}
		if f[v] == 2 {
			hasUse[cid] = true
		}
	}

	// DP over DAG: fromAssign[c] = reachable from some assign SCC without passing another assign SCC.
	// We'll propagate from SCCs that haveAssign, but stop when reaching SCCs that also haveAssign (no need to propagate further).
	// However, we must allow starting SCC itself even if hasAssign.
	fromAssign := make([]bool, cc)

	// We can perform multi-source BFS/DFS from all assign SCCs.
	queue := make([]int, 0)
	inQueue := make([]bool, cc)

	for c := 0; c < cc; c++ {
		if hasAssign[c] {
			fromAssign[c] = true
			queue = append(queue, c)
			inQueue[c] = true
		}
	}

	for len(queue) > 0 {
		v := queue[0]
		queue = queue[1:]
		inQueue[v] = false
		for _, to := range cg[v] {
			// If 'to' has assign, we should not propagate further through it,
			// but we still mark it reachable (since path may end there).
			if !fromAssign[to] {
				fromAssign[to] = true
				// propagate further only if 'to' has no assign
				if !hasAssign[to] && !inQueue[to] {
					queue = append(queue, to)
					inQueue[to] = true
				}
			}
		}
	}

	// Now, for each SCC, interesting if:
	// fromAssign[c] == true AND hasUse reachable from c without passing another assign SCC.
	// But our DP already ensured paths from assign SCCs to all SCCs without intermediate assign SCCs.
	// So any SCC with fromAssign[c] and hasUse[c] is good.
	interestingComp := make([]bool, cc)
	for c := 0; c < cc; c++ {
		if fromAssign[c] && hasUse[c] {
			interestingComp[c] = true
		}
	}

	// However, we must ensure that between assign SCC and use SCC there is no other assign SCC.
	// Our propagation stopped at assign SCCs, so this holds.

	// Now, any node in an SCC that lies on some path between an assign SCC and a use SCC (with no other assign)
	// is interesting. That means: any SCC that is both reachable from some assign SCC (fromAssign[c])
	// and can reach some use SCC (under same constraint). We only did forward DP.
	// Need backward DP from use SCCs similarly, stopping at assign SCCs.

	toUse := make([]bool, cc)
	queue = queue[:0]
	for c := 0; c < cc; c++ {
		if hasUse[c] {
			toUse[c] = true
			queue = append(queue, c)
			inQueue[c] = true
		} else {
			inQueue[c] = false
		}
	}

	// Build reverse condensation graph
	rcg := make([][]int, cc)
	for v := 0; v < cc; v++ {
		for _, to := range cg[v] {
			rcg[to] = append(rcg[to], v)
		}
	}

	for len(queue) > 0 {
		v := queue[0]
		queue = queue[1:]
		inQueue[v] = false
		for _, to := range rcg[v] {
			if !toUse[to] {
				toUse[to] = true
				if !hasAssign[to] && !inQueue[to] {
					queue = append(queue, to)
					inQueue[to] = true
				}
			}
		}
	}

	// SCC is on some valid path if fromAssign[c] && toUse[c]
	onPath := make([]bool, cc)
	for c := 0; c < cc; c++ {
		if fromAssign[c] && toUse[c] {
			onPath[c] = true
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	for i := 0; i < n; i++ {
		if onPath[comp[i]] {
			fmt.Fprintln(out, 1)
		} else {
			fmt.Fprintln(out, 0)
		}
	}
}
