		a--
		b--
		g[a] = append(g[a], b)
		gr[b] = append(gr[b], a)
	}

	// Kosaraju for SCC
	order := make([]int, 0, n)
	used := make([]bool, n)

	var dfs1 func(v int)
	dfs1 = func(v int) {
