				dfs1(to)
			}
		}
		order = append(order, v)
	}

	for i := 0; i < n; i++ {
		if !used[i] {
			dfs1(i)
		}
	}

	comp := make([]int, n)
	for i := range comp {
		comp[i] = -1
	}
	var dfs2 func(v, c int)
	dfs2 = func(v, c int) {
		comp[v] = c
		for _, to := range gr[v] {
			if comp[to] == -1 {
				dfs2(to, c)
			}
		}
	}

	cc := 0
	for i := n - 1; i >= 0; i-- {
		v := order[i]
		if comp[v] == -1 {
			dfs2(v, cc)
			cc++
		}
	}

	// Build condensation DAG
	cg := make([][]int, cc)
	crg := make([][]int, cc)
	for v := 0; v < n; v++ {
		cv := comp[v]
		for _, to := range g[v] {
			ct := comp[to]
			if cv != ct {
				cg[cv] = append(cg[cv], ct)
				crg[ct] = append(crg[ct], cv)
			}
		}
	}

	// Remove duplicate edges in condensation graph (optional but safer)
	removeDup := func(adj [][]int) {
		for i := range adj {
			if len(adj[i]) <= 1 {
				continue
			}
			mp := make(map[int]struct{}, len(adj[i]))
			newList := make([]int, 0, len(adj[i]))
			for _, v := range adj[i] {
				if _, ok := mp[v]; !ok {
					mp[v] = struct{}{}
					newList = append(newList, v)
				}
			}
			adj[i] = newList
		}
	}
	removeDup(cg)
	removeDup(crg)

	// Mark SCCs that contain assign/use
	assignComp := make([]bool, cc)
	useComp := make([]bool, cc)
	for v := 0; v < n; v++ {
		c := comp[v]
		if f[v] == 1 {
			assignComp[c] = true
		}
		if f[v] == 2 {
			useComp[c] = true
		}
	}

	// DP from assign: forward reachability without passing another assign
	// We'll compute for each SCC whether there exists a path starting from
	// some assign SCC to this SCC without visiting any other assign SCC.
	// Actually we need two directions:
	// 1) from assign to others (forward)
	// 2) from others to use (backward)
	// Both must avoid intermediate assign SCCs.

	// Topological order of condensation graph
	inDeg := make([]int, cc)
	for v := 0; v < cc; v++ {
		for _, to := range cg[v] {
			inDeg[to]++
		}
	}
	queue := make([]int, 0, cc)
	for i := 0; i < cc; i++ {
		if inDeg[i] == 0 {
			queue = append(queue, i)
		}
	}
	top := make([]int, 0, cc)
	for len(queue) > 0 {
		v := queue[0]
		queue = queue[1:]
		top = append(top, v)
		for _, to := range cg[v] {
			inDeg[to]--
			if inDeg[to] == 0 {
				queue = append(queue, to)
			}
		}
	}

	// forward DP
	forward := make([]bool, cc)
	for i := 0; i < cc; i++ {
		if assignComp[i] {
			forward[i] = true
		}
	}
	for _, v := range top {
		if !forward[v] {
			continue
		}
		for _, to := range cg[v] {
			if assignComp[to] {
				// cannot pass through another assign SCC
				continue
			}
			if !forward[to] {
				forward[to] = true
			}
		}
	}

	// backward DP from use
	outDeg := make([]int, cc)
	for v := 0; v < cc; v++ {
		for _, to := range cg[v] {
			outDeg[v]++
		}
	}
	queue = queue[:0]
	for i := 0; i < cc; i++ {
		if outDeg[i] == 0 {
			queue = append(queue, i)
		}
	}
	revt := make([]int, 0, cc)
	for len(queue) > 0 {
		v := queue[0]
		queue = queue[1:]
		revt = append(revt, v)
		for _, from := range crg[v] {
			outDeg[from]--
			if outDeg[from] == 0 {
				queue = append(queue, from)
			}
		}
	}

	backward := make([]bool, cc)
	for i := 0; i < cc; i++ {
		if useComp[i] {
			backward[i] = true
		}
	}
	for _, v := range revt {
		if !backward[v] {
			continue
		}
		for _, from := range crg[v] {
			if assignComp[from] {
				continue
			}
			if !backward[from] {
				backward[from] = true
			}
		}
	}

	// Now a SCC is "interesting" if:
	// - it is an assign SCC and can reach some use SCC without another assign
	//   (i.e., forward[v] && backward[v])
	// - or it lies on a path between such assign and use SCCs (forward[v] && backward[v])
	interestingComp := make([]bool, cc)
	for i := 0; i < cc; i++ {
		if forward[i] && backward[i] {
			interestingComp[i] = true
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	for i := 0; i < n; i++ {
		if interestingComp[comp[i]] {
			fmt.Fprintln(out, 1)
		} else {
			fmt.Fprintln(out, 0)
		}
	}
}
